void subs(int i, int[] a, List<Integer> cur, List<List<Integer>> res) {
    if (i == a.length) { res.add(cur); return; }   // no copy
    cur.add(a[i]);
    subs(i + 1, a, cur, res);
    cur.remove(cur.size() - 1);
    subs(i + 1, a, cur, res);
}

void letters(int idx, String digits, StringBuilder sb, List<String> res) {
    if (idx == digits.length()) { res.add(sb.toString()); return; }
    for (char ch : KEYS[digits.charAt(idx) - '0'].toCharArray()) {
        sb.append(ch);
        letters(idx + 1, digits, sb, res);
        sb.deleteCharAt(sb.length() - 1);
    }
}

